import{_ as a,o,c as t,a5 as n}from"./chunks/framework.BEZBAInb.js";const c=JSON.parse('{"title":"Install Konado","description":"","frontmatter":{"title":"Install Konado","order":1},"headers":[],"relativePath":"en/2.4/tutorial/install.md","filePath":"en/2.4/tutorial/install.md","lastUpdated":1788455378000}'),l={name:"en/2.4/tutorial/install.md"};function i(r,e,s,d,u,h){return o(),t("div",null,[...e[0]||(e[0]=[n('<h1 id="install-konado" tabindex="-1">Install Konado <a class="header-anchor" href="#install-konado" aria-label="Permalink to &quot;Install Konado&quot;">​</a></h1><h2 id="requirements" tabindex="-1">Requirements <a class="header-anchor" href="#requirements" aria-label="Permalink to &quot;Requirements&quot;">​</a></h2><p>Requires <strong>Godot 4.6 or higher</strong>.</p><p>The following Godot versions have been tested by the developers and work correctly:</p><ul><li>4.6</li><li>4.5.1</li><li>4.5</li></ul><h3 id="plugin-download" tabindex="-1">Plugin Download <a class="header-anchor" href="#plugin-download" aria-label="Permalink to &quot;Plugin Download&quot;">​</a></h3><h4 id="stable-version-recommended" tabindex="-1">Stable Version (Recommended) <a class="header-anchor" href="#stable-version-recommended" aria-label="Permalink to &quot;Stable Version (Recommended)&quot;">​</a></h4><p>Go to the <a href="https://github.com/godothub/konado/releases/latest" target="_blank" rel="noreferrer">latest Konado release page</a> and download the latest stable plugin ZIP package. The stable version has been fully verified and provides better stability and reliability, making it the preferred choice for production environments.</p><p>To improve the download experience for users in mainland China, we recommend using this optimized resource link: <a href="https://atomgit.com/godothub/konado/releases" target="_blank" rel="noreferrer">Release link</a>, which can effectively improve download speed.</p><h4 id="daily-build-preview-version" tabindex="-1">Daily Build (Preview Version) <a class="header-anchor" href="#daily-build-preview-version" aria-label="Permalink to &quot;Daily Build (Preview Version)&quot;">​</a></h4><p>We also provide daily builds. If you want to try the latest development features, go to the <a href="https://github.com/godothub/konado/releases/" target="_blank" rel="noreferrer">Konado all releases page</a> and look for releases whose title contains <code>Konado Daily Build</code>.</p><p>If you are a developer and want to try the latest development features, you can download the daily build and report any issues you encounter to Issues.</p><blockquote><p>Caution: Daily builds are only for trying the latest development features. Because they contain new features that have not been fully tested, unfixed bugs may exist. <strong>Do not use them in production environments</strong>. Choose carefully based on your actual needs.</p></blockquote><h2 id="installation-steps" tabindex="-1">Installation Steps <a class="header-anchor" href="#installation-steps" aria-label="Permalink to &quot;Installation Steps&quot;">​</a></h2><ol><li>Create a new plugin folder <code>addons</code> in the Godot project directory</li><li>Download the plugin zip package from the release page</li><li>Extract it into the <code>addons</code> directory</li><li>Enable the plugin in Godot project settings and reload the current project</li></ol><blockquote><p>Tip: Some errors may appear when installing and enabling the plugin for the first time. They can be ignored; reload the project afterward.</p></blockquote><h2 id="message-from-the-development-team" tabindex="-1">Message from the Development Team <a class="header-anchor" href="#message-from-the-development-team" aria-label="Permalink to &quot;Message from the Development Team&quot;">​</a></h2><p>You have successfully installed the Konado plugin. Before you officially start creating, we would like to share a message with you:</p><blockquote><p>&quot;For any industry, imagination paired with a touch of wisdom is an invincible weapon.&quot;</p><p>-- Philip K. Dick<br><em>Minority Report</em> (1956)</p></blockquote><p>May you always keep your imagination and commitment to refinement, and explore more possibilities on your creative journey.</p>',20)])])}const m=a(l,[["render",i]]);export{c as __pageData,m as default};
